/* ===== hair =====
   Every style was painted on these very heads, so its place comes from the art: HAIR_FIT
   (hair-fit.js, generated by art/fit_hair_pack2.py) registers each worn proof to the base doll and
   gives the sprite's rect {x, y, w, h, rot} per doll and view. HAIR_TUNE[id][doll][view] holds what
   registration cannot know, judged by eye against the proofs (art/lab.html?sheet=proofs):
   - dx, dy: shift (doll px); kx, ky: scale about `at` (doll px, default the head's centre) where her
     head is shaped differently from the proof's;
   - layer: 'arms' = in front of the body except where it hangs over the arms (front view, ARMS_CLEAR),
     'side' = in front of head, neck and back but behind the near arm and shoulder (side views, the
     view's arm polygon), 'neck' = only the head region in front, lengths behind the neck and back
     (FRONT_SIDE, mirrored for the right view), 'top' = all in front, or a list of doll-local shapes
     drawn in front. The sprites only hold what shows on the proof, so the head never needs masking;
   - earsUnder: the style covers her ears (earrings drawn under it);
   - clip {x, y, rot, scale, behind, hide}: where a hair accessory sits (on the hair, per view);
   - soften / shade / scalp / cut / cutDoll as in portrait.js hairLayers;
   - k / kx / ky with at: see above.
   Defaults: front 'arms' when the style reaches below her shoulders, else 'top'; side
   views 'side'; back 'top'; clips at the head's default spot of the view. */
/* the face kept clear of front hair (portrait.js openFace), [y, xl, xr] rows in the front view: from the
   brows past the outer eye corners and the cheekbones, along the jaw to the chin. Also what the
   face-open check (art/lab.html?sheet=faceopen, test/face-open.test.mjs) measures. */
const FACE_OPEN={adult:[[66,168,249],[86,166,248],[100,163,247],[120,166,241],[140,177,233],[157,196,222]],
  little:[[97,150,264],[122,152,262],[150,150,263],[170,158,256],[190,170,244],[205,190,222]]};
const UNDER_ROWS={adult:{y0:28,y1:200,gap:24,dark:.68},little:{y0:60,y1:250,gap:28,dark:.68}};
/* styles that show the ears: the same fill only in the temple band, from the hairline to the top of the
   ear, so the hair meets her temple there while the ear and earring stay fully visible */
const TEMPLE_ROWS={adult:{y0:28,y1:82,gap:16,dark:.68},little:{y0:60,y1:110,gap:18,dark:.68}};
const HEAD_C={adult:{front:[200,62],back:[200,62],left:[90,62],right:[91,62]},little:{front:[203,105],back:[203,105],left:[110,105],right:[99,105]}};
const SHOULDER_Y={adult:178,little:236};
const CLIP_AT={adult:{front:{x:162,y:32,rot:-25},left:{x:122,y:24,behind:true},right:{x:59,y:24},back:{x:238,y:34,rot:20,scale:.85}},
  little:{front:{x:138,y:58,rot:-20},left:{x:140,y:50,behind:true},right:{x:67,y:50},back:{x:264,y:58,rot:15,scale:.85}}};
/* HAIR_TUNE[id][doll] = {all: tune for every view, front|left|right|back: per view (wins)} */
const UNDER={all:{earsUnder:true}};
const HAIR_TUNE={
  'long-waves':{adult:UNDER},'half-up-curls':{adult:UNDER},'sleek-curtain-bangs':{adult:UNDER},'flip-bob':{adult:UNDER},
  'space-buns':{adult:UNDER},
  /* round 2 redraw: a small gap the proof's head left at her right temple is backed with hair, and the
     gaps between the curls are background, not scalp */
  'crimped-twists':{adult:{all:{earsUnder:true},front:{scalp:false,holeFill:[{ellipse:[262,86,6,8]}]}}},
  /* round 2 redraw: the hair tucked behind her right ear lies a little outside her narrower head, so the
     strip between them is filled from behind (underHair) down past the jaw, and the gap the proof's ear
     left in the hair at her temple is backed with hair (holeFill); the gap between the ponytail and its
     loose strand is background, not scalp */
  'side-ponytail':{adult:{front:{under:{y0:28,y1:150},scalp:false,holeFill:[{ellipse:[260,93,7,14]}]}}},
  /* round 2 redraw: a fine flyaway strand runs just outside the crown; the gap under it is background,
     not scalp (scalpShow would paint it as a bald rim) */
  'curly-bob':{little:{all:{scalp:false}}},
  /* its baby curls cross the brows on purpose (as on the proof): the face is not opened through them */
  'ringlet-pigtails':{little:{front:{open:false}}},
  /* her skull is a little rounder at the back than the toddler proofs': in profile these short styles
     grow 2-2.5% about the forehead so no scalp peeks out behind them */
  'pixie-sweep':{little:{left:{k:1.025,at:[40,130]},right:{k:1.025,at:[167,130]}}},
  'chin-bob-bangs':{little:{all:{earsUnder:true},left:{k:1.02,at:[40,130]},right:{k:1.02,at:[167,130]}}},
  'wavy-crop':{little:{all:{earsUnder:true},left:{k:1.02,at:[40,130]},right:{k:1.02,at:[167,130]}}}
};
const mirrorShapes=(list,M)=>list.map(s=>s.poly?{...s,poly:s.poly.map(([x,y])=>[M-x,y])}:s);
for(const it of items)if(it.category==='hair'){
  it.lum=HAIR_LUM[it.id];
  for(const doll of it.dolls){
    const fits=HAIR_FIT[it.id]?.[doll];if(!fits)continue;
    for(const view of HAIR_VIEWS){
      const f=fits[view],tn=HAIR_TUNE[it.id]?.[doll]||{},t={...tn.all,...tn[view]};if(!f||t.skip)continue;
      const [ax,ay]=t.at||HEAD_C[doll][view],kx=t.kx??t.k??1,ky=t.ky??t.k??1;
      const fit={x:ax+(f.x-ax)*kx+(t.dx||0),y:ay+(f.y-ay)*ky+(t.dy||0),w:f.w*kx,h:f.h*ky};
      if(f.rot||t.rot)fit.rot=(f.rot||0)+(t.rot||0);
      const layer=t.layer||(view==='front'?(f.y+f.h>SHOULDER_Y[doll]+20?'arms':'top'):view==='back'?'top':'side');
      if(layer==='arms')fit.front=ARMS_CLEAR[doll];
      else if(layer==='side')fit.behind=[{poly:dolls[doll].views[view].arm,feather:2}];
      else if(layer==='neck')fit.front=view==='right'?mirrorShapes(FRONT_SIDE[doll],MIRROR[doll]):FRONT_SIDE[doll];
      else if(Array.isArray(layer))fit.front=layer;
      fit.clip={...CLIP_AT[doll][view],...t.clip};
      if(view==='front'&&t.open!==false)fit.open={rows:FACE_OPEN[doll],...t.open};
      for(const k of ['earsUnder','soften','shade','scalp','scalpFill','holeFill','cut','cutDoll'])if(t[k]!==undefined)fit[k]=t[k];
      // ears covered: hair behind the head fills the strip between skin and hair (portrait.js underHair)
      if(view==='front'&&t.under!==false)fit.under={...(fit.earsUnder?UNDER_ROWS:TEMPLE_ROWS)[doll],...t.under};
      (it.fit[doll]??={})[view]=fit;
    }
  }
}

/* ===== the second wardrobe =====
   Outfits and shoes from the pack2 sheets (and the round 2 redraws): placed by registration in all four
   views and written by art/fit_wear.py with their game-size sprites (assets/wear/<id>-<view>[-part].webp,
   scale `s` of the full-resolution slices, and a 160 px card picture in assets/wear/thumbs/). The fit
   format is the same as above. WEAR_INFO adds what the sprites cannot say: colourways, open toes. */
